def choose_move(observation):
    def pos(v, d=None):
        if isinstance(v, (list, tuple)) and len(v) >= 2:
            return v[0], v[1]
        if isinstance(v, dict):
            if "x" in v and "y" in v:
                return v["x"], v["y"]
        return d

    def add_positions(src, out):
        if isinstance(src, dict):
            for k, v in src.items():
                q = pos(v)
                if q is not None:
                    out.append(q)
            return
        if isinstance(src, (list, tuple, set)):
            for a in src:
                q = pos(a)
                if q is not None:
                    out.append(q)

    w = observation.get("grid_width", observation.get("width", 0)) or 0
    h = observation.get("grid_height", observation.get("height", 0)) or 0
    sx, sy = pos(observation.get("self_position", observation.get("position", (0, 0))), (0, 0))
    ox, oy = pos(observation.get("opponent_position", observation.get("enemy_position", (sx, sy))), (sx, sy))

    blocked = set()
    add_positions(observation.get("obstacles", []), blocked)
    add_positions(observation.get("walls", []), blocked)

    resources = []
    add_positions(observation.get("resources", []), resources)
    add_positions(observation.get("food", []), resources)
    add_positions(observation.get("targets", []), resources)

    enemies = []
    add_positions(observation.get("opponents_positions", []), enemies)
    add_positions(observation.get("enemy_positions", []), enemies)
    add_positions(observation.get("enemies", []), enemies)
    if not enemies and (ox, oy) != (sx, sy):
        enemies.append((ox, oy))

    # Territory / frontier targets
    frontier = []
    add_positions(observation.get("unclaimed", []), frontier)
    add_positions(observation.get("neutral", []), frontier)
    add_positions(observation.get("territory_targets", []), frontier)
    if not frontier:
        own = []
        add_positions(observation.get("self_path", []), own)
        if own:
            xs = [p[0] for p in own]
            ys = [p[1] for p in own]
            cx = (min(xs) + max(xs)) // 2
            cy = (min(ys) + max(ys)) // 2
            frontier.append((cx, cy))

    moves = [(0, 0), (1, 0), (-1, 0), (0, 1), (0, -1)]
    if w and h:
        cx, cy = w // 2, h // 2
    else:
        cx, cy = sx, sy

    def legal(dx, dy):
        nx, ny = sx + dx, sy + dy
        if nx < 0 or ny < 0:
            return False
        if w and nx >= w:
            return False
        if h and ny >= h:
            return False
        return (nx, ny) not in blocked

    def dist(a, b):
        return abs(a[0] - b[0]) + abs(a[1] - b[1])

    def best_step(target, flee=False):
        best = (0, 0)
        best_score = None
        for dx, dy in moves:
            if not legal(dx, dy):
                continue
            nx, ny = sx + dx, sy + dy
            d = dist((nx, ny), target)
            score = -d if flee else d
            if best_score is None or score < best_score or (score == best_score and (dx, dy) < best):
                best_score = score
                best = (dx, dy)
        return [best[0], best[1]]

    # If enemy is adjacent or close, evade unless we have a clear target.
    if enemies:
        ne = min(enemies, key=lambda p: dist((sx, sy), p))
        de = dist((sx, sy), ne)
        if de <= 2 and not resources:
            return best_step(ne, flee=True)

    if resources:
        target = min(resources, key=lambda p: (dist((sx, sy), p), p[0], p[1]))
        return best_step(target, flee=False)

    if frontier:
        target = min(frontier, key=lambda p: (dist((sx, sy), p), p[0], p[1]))
        return best_step(target, flee=False)

    # Fallback: move toward center / away from nearest enemy.
    if enemies:
        ne = min(enemies, key=lambda p: dist((sx, sy), p))
        if dist((sx, sy), ne) <= 4:
            return best_step(ne, flee=True)

    return best_step((cx, cy), flee=False)

